import numpy as np

def softmax(Z):
    Z = Z - np.max(Z, axis=1, keepdims=True)
    exp_Z = np.exp(Z)
    return exp_Z / np.sum(exp_Z, axis=1, keepdims=True)

def cross_entropy(Z, y):
    Z = Z - np.max(Z, axis=1, keepdims=True)
    log_probs = Z - np.log(np.sum(np.exp(Z), axis=1, keepdims=True))
    n = Z.shape[0]
    return -np.mean(log_probs[np.arange(n), y])
