    out = bytearray()
    i = 0
    while i < len(data):
        code = data[i]
        if code == 0:
            raise ValueError("zero byte in input")
        i += 1
        if i + code - 1 > len(data):
            raise ValueError("group runs past end")
        out.extend(data[i:i + code - 1])
        i += code - 1
        if code < 255:
            if i == len(data):
                break
            out.append(0)
    return bytes(out)
