__global__ void block_sum(const float* in, float* out, int n)
{
    extern __shared__ float sdata[];
    int tid = threadIdx.x;
    int i = blockIdx.x * blockDim.x + tid;
    sdata[tid] = (i < n) ? in[i] : 0.0f;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        out[blockIdx.x] = sdata[0];
    }
}

double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad) {
    const double* W1 = params;
    const double* b1 = params + n_hidden * n_in;
    const double* W2 = b1 + n_hidden;
    double b2 = W2[n_hidden];

    double* gW1 = grad;
    double* gb1 = grad + n_hidden * n_in;
    double* gW2 = gb1 + n_hidden;
    double* gb2 = gW2 + n_hidden;

    for (int i = 0; i < n_hidden * n_in; ++i) gW1[i] = 0.0;
    for (int i = 0; i < n_hidden; ++i) gb1[i] = 0.0;
    for (int i = 0; i < n_hidden; ++i) gW2[i] = 0.0;
    *gb2 = 0.0;

    double total_loss = 0.0;

    for (int s = 0; s < n_samples; ++s) {
        const double* x = X + s * n_in;
        double y_s = y[s];

        double h[64]; // assume n_hidden <= 64 for stack allocation
        double z = b2;
        for (int j = 0; j < n_hidden; ++j) {
            double sum = b1[j];
            const double* w1j = W1 + j * n_in;
            for (int k = 0; k < n_in; ++k) {
                sum += w1j[k] * x[k];
            }
            h[j] = tanh(sum);
            z += W2[j] * h[j];
        }

        double p = 1.0 / (1.0 + exp(-z));
        double loss = -(y_s * log(p) + (1.0 - y_s) * log(1.0 - p));
        total_loss += loss;

        double dz = p - y_s; // dL/dz

        *gb2 += dz;
        for (int j = 0; j < n_hidden; ++j) {
            gW2[j] += dz * h[j];
            double dh = dz * W2[j] * (1.0 - h[j] * h[j]); // dL/d(sum_j)
            gb1[j] += dh;
            const double* w1j = W1 + j * n_in;
            double* gw1j = gW1 + j * n_in;
            for (int k = 0; k < n_in; ++k) {
                gw1j[k] += dh * x[k];
            }
        }
    }

    double inv_n = 1.0 / n_samples;
    for (int i = 0; i < n_hidden * n_in; ++i) gW1[i] *= inv_n;
    for (int i = 0; i < n_hidden; ++i) gb1[i] *= inv_n;
    for (int i = 0; i < n_hidden; ++i) gW2[i] *= inv_n;
    *gb2 *= inv_n;

    return total_loss * inv_n;
}

struct Tape {
    struct Node {
        double val;
        double grad;
        int op; // 0=const,1=input,2=add,3=mul,4=sin,5=exp
        int a, b;
    };
    std::vector<Node> nodes;

    int constant(double v) {
        nodes.push_back({v, 0.0, 0, -1, -1});
        return (int)nodes.size() - 1;
    }
    int input(double v) {
        nodes.push_back({v, 0.0, 1, -1, -1});
        return (int)nodes.size() - 1;
    }
    int add(int a, int b) {
        nodes.push_back({nodes[a].val + nodes[b].val, 0.0, 2, a, b});
        return (int)nodes.size() - 1;
    }
    int mul(int a, int b) {
        nodes.push_back({nodes[a].val * nodes[b].val, 0.0, 3, a, b});
        return (int)nodes.size() - 1;
    }
    int sin_(int a) {
        nodes.push_back({std::sin(nodes[a].val), 0.0, 4, a, -1});
        return (int)nodes.size() - 1;
    }
    int exp_(int a) {
        nodes.push_back({std::exp(nodes[a].val), 0.0, 5, a, -1});
        return (int)nodes.size() - 1;
    }
    double value(int node) const { return nodes[node].val; }
    void backward(int root) {
        nodes[root].grad = 1.0;
        for (int i = (int)nodes.size() - 1; i >= 0; --i) {
            double g = nodes[i].grad;
            if (g == 0.0) continue;
            switch (nodes[i].op) {
                case 2: // add
                    nodes[nodes[i].a].grad += g;
                    nodes[nodes[i].b].grad += g;
                    break;
                case 3: // mul
                    nodes[nodes[i].a].grad += g * nodes[nodes[i].b].val;
                    nodes[nodes[i].b].grad += g * nodes[nodes[i].a].val;
                    break;
                case 4: // sin
                    nodes[nodes[i].a].grad += g * std::cos(nodes[nodes[i].a].val);
                    break;
                case 5: // exp
                    nodes[nodes[i].a].grad += g * nodes[i].val;
                    break;
            }
        }
    }
    double grad(int node) const { return nodes[node].grad; }
};

