    if (!wrst_n) begin
      wptr_bin <= {PTRW{1'b0}};
      wptr_gray <= {PTRW{1'b0}};
    end else if (winc && !wfull) begin
      wptr_bin <= wptr_bin + 1'b1;
      wptr_gray <= (wptr_bin + 1'b1) ^ ((wptr_bin + 1'b1) >> 1);
