      rptr_bin <= {PTRW{1'b0}};
      rptr_gray <= {PTRW{1'b0}};
    end else if (rinc && !rempty) begin
      rptr_bin <= rptr_bin + 1'b1;
      rptr_gray <= (rptr_bin + 1'b1) ^ ((rptr_bin + 1'b1) >> 1);
    end
  end

  // Synchronize read pointer to write clock
  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wq1_rptr <= {PTRW{1'b0}};
      wq2_rptr <= {PTRW{1'b0}};
    end else begin
      wq1_rptr <= rptr_gray;
