  // Synchronize write pointer to read clock
  always @(posedge rclk or negedge rrst_n) begin
    if (!rrst_n) begin
      rq1_wptr <= {PTRW{1'b0}};
      rq2_wptr <= {PTRW{1'b0}};
    end else begin
      rq1_wptr <= wptr_gray;
      rq2_wptr <= rq1_wptr;
    end
  end

  // Full and empty generation
  assign wfull = (wptr_gray == {~wq2_rptr[PTRW-1:PTRW-2], wq2_rptr[PTRW-3:0]});
  assign rempty = (rptr_gray == rq2_wptr);

  // Memory write
  always @(posedge wclk) begin
    if (winc && !wfull)
      mem[waddr] <= wdata;
  end

  // Memory read (combinational)
  assign rdata = mem[raddr];

endmodule

